# --- main.tf ---
terraform {
  required_providers { aws = { source = "hashicorp/aws", version = "~> 5.0" } }
  backend "s3" {                       # remote state + locking
    bucket         = "tfstate-data-eng"
    key            = "orders/terraform.tfstate"
    region         = "us-east-1"
    dynamodb_table = "tf-locks"          # state lock table
    encrypt        = true
  }
}

provider "aws" { region = "us-east-1" }

variable "env" { default = "dev" }

resource "aws_s3_bucket" "landing" {
  bucket = "data-eng-orders-${var.env}"
}

resource "aws_s3_bucket_versioning" "landing" {
  bucket = aws_s3_bucket.landing.id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "landing" {
  bucket = aws_s3_bucket.landing.id
  rule {
    bucket_key_enabled = true
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = "alias/etl-data"
    }
  }
}

# Workflow:
#   terraform init      # download providers, configure S3 backend + lock
#   terraform plan      # preview: '+ 3 to add, 0 to change, 0 to destroy'
#   terraform apply     # execute after review; updates state file
